	title 'QD Rects             GS ROM 2.0'*****************************************************************			   **              RECTS		   **			   **********************************************************************************************************************************			   **	Copyright (C) 1985-1990	   **	All Rights Reserved		   **	Apple Computer, Inc.	   **			   ******************************************************************* 26-Sep-90	Dave Lyons** Brought in macros from old nonstandard all.macros.**	string asis	blanks off		include 'all.macros'	include ':QDEquates:qd.data.asm'	INCLUDE ':QDEquates:core.globals1'	INCLUDE ':QDEquates:core.globals2'	INCLUDE ':QDEquates:region.equs'	INCLUDE ':QDEquates:rect.equs'	INCLUDE ':QDEquates:slab.equs'		include '::sys.equs.asm'	MACRO&lab	PushPtr &addr&lab	dc.B $F4	dc.W (&addr)>>16	dc.B $F4	dc.W &addr	MEND****************************************************************** macros for branching on conditions that take more than one* instruction. macros for LONG conditional branching*****************************************************************;---------------------------------------------------------	MACRO	ble &A		blt  &A		beq  &A	MEND;---------------------------------------------------------	MACRO	bgt &A		beq  @dontTake		bge  &A@dontTake	MEND;---------------------------------------------------------	MACRO	bcsl &A		bcc  @dontTake		brl  &A@dontTake	MEND;---------------------------------------------------------	MACRO	bccl &A		bcs  @dontTake		brl  &A@dontTake	MEND;---------------------------------------------------------	MACRO	beql &A		bne  @dontTake		brl  &A@dontTake	MEND;---------------------------------------------------------	MACRO	bnel &A		beq  @dontTake		brl  &A@dontTake	MEND;---------------------------------------------------------	MACRO	bltl &A		bge  @dontTake		brl  &A@dontTake	MEND;---------------------------------------------------------	MACRO	bgel &A		blt  @dontTake		brl  &A@dontTake	MEND;---------------------------------------------------------	MACRO	bmil &A		bpl  @dontTake		brl  &A@dontTake	MEND;---------------------------------------------------------	MACRO	bpll &A		bmi  @dontTake		brl  &A@dontTake	MEND;---------------------------------------------------------	MACRO	blel &A		blt  @takeBranch		bne  @dontTake@takeBranch	brl  &A@dontTake	MEND;---------------------------------------------------------	MACRO	bgtl &A		blt  @dontTake		beq  @dontTake		brl  &A@dontTake	MEND;---------------------------------------------------------		macro	SwapPat; This macro will test to see if the patter needs to be swapped and it will do so if ; it needs it. I only do it here as an 11th hour fix to a dastardly problem	lda <StartWord	; get the starting word number	and #$0002	; see if its an odd word or even word	beq @NoSwapNeeded	; if zero, don't swap	ldx <pat	lda <pat+2	sta <pat	stx <Pat+2@NoSwapNeeded		; now continue	ENDM	; Some handy rectange equateso_V1	equ 0o_H1	equ 2o_V2	equ 4o_H2	equ 6;-----------------------------------------------;;   Imported addresses;;-----------------------------------------------	IMPORT BusyErr4	IMPORT BusyErr8	IMPORT DerefC	IMPORT DrawRgn	IMPORT FastSlabBIC	IMPORT FastSlabCopy	IMPORT FastSlabOR	IMPORT FastSlabXOR	IMPORT GetBoundsC	IMPORT MinRectToY1	IMPORT QDStart	IMPORT RgnSave	IMPORT SlabBIC	IMPORT SlabCopy	IMPORT SlabOR	IMPORT SlabXOR	IMPORT TestGPs	IMPORT UnlockC;-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY CallRect	ENTRY CheckPenVis	ENTRY FastSlabTable	ENTRY FrRect	ENTRY GetRect	ENTRY GrabPenSize	ENTRY JoinRect	ENTRY LeftMaskTable	ENTRY NextPatSlice	ENTRY RightMaskTable	ENTRY SetFirstDestRef	ENTRY SetNextDestRef	ENTRY SlabTable	ENTRY XSetUp640	ENTRY iDrawRect;                COPY RECTS/SLAB.SETUP****************************************************************** SetSlabAdr** This routine sets	of the vector "ToSlab" in bank E0.  All* drawing routines use this vector to get to their slab routine.** If the clipping is non-rectangular or	the drawing mask is* not all $FFFF's, then we use the normal slabs.  Otherwise* we use the FAST SLABS.** 2/28/89	Konstantin and Dave* Also, returned in carry whether a fast slab is being used, and* returned in <X> is the offset to the slab table. THIS SHOULD* NOT CHANGE****************************************************************iSetSlabAdr	PROC EXPORT	lda FillMode	and #$7F	asl a	asl a	tax	lda NonRectRegions	bne GoSlow	ldy #o_PnMask	;go fast if there is no mask	lda [PortRef],y	ldy #o_PnMask+2	and [PortRef],y	ldy #o_PnMask+4	and [PortRef],y	ldy #o_PnMask+6	and [PortRef],y	inc a	;are they all $FFFF?	beq  GoFastGoSlow		; 	lda >SlabTable,x	sta >ToSlab	lda >SlabTable+2,x	sta >ToSlab+2	sec	;we must go slow	rtlGoFast	lda >FastSlabTable,x	sta >ToSlab	lda >FastSlabTable+2,x	sta >ToSlab+2	clc	;signals that we can go fast	rtl	ENDP****************************************************************** SlabTable*****************************************************************SlabTable	PROC EXPORT	jml SlabCopy	jml SlabOR	jml SlabXOR	jml SlabBIC	ENDP****************************************************************** FastSlabTable*****************************************************************FastSlabTable	PROC EXPORT	jml FastSlabCopy	jml FastSlabOR	jml FastSlabXOR	jml FastSlabBIC	ENDP****************************************************************** PreDRAW** Puts the pen pattern into TheFillPat and the pen mode into* FillMode*****************************************************************iPreDraw	PROC EXPORT	ldx #512	lda <DirtyDPFlags,x	and #PreDrawOK	; Fixed to and by Mensch 4/24/89	cmp #PreDrawOK	beq @PreDrawDone		jsl PortLoc2ZP	; get the port info	down to zp	jsl GetPenPReady	; get the pattern down to zp	jsl GetMaskReady@PreDrawDone	ldy #O_PnMode	; get the mode down	to zp	lda [PortRef],y	sta FillMode	rtl	ENDP****************************************************************** XSetUp** suck up 4 cycles...****************************************************************iXSetUp	PROC EXPORT	bit MasterSCB-1	bmi XSetUp640	ENDP****************************************************************** XSetUp320*****************************************************************XSetUp320	PROC EXPORT	lda X1	; convert local coordinates to	sec	; memory coordinates	sbc BoundsRect+2	; start with left point	tay	; save copy in y	and #3	; mask off all but low 2 bits	asl a	; quadruple result and put in	asl a	tax	; x	tya	; retrieve y and half it so it refers	lsr a	; to a byte (not a pixel)	and #$FFFF-1	; make it even	sta StartWord	lda >LeftMaskTable,x	sta LeftMask	; across words don't work for pixels	lda X2	; convert local coordinates to	clc	sbc BoundsRect+2; dec a See 640mode for comment	; one less so don't overwrite limit	tay	; save copy in y	and #3	; mask off all but low 2 bits	asl a	; quadruple result and put in	asl a	tax	; x	tya	; retrieve y and half it so it refers	lsr a	; to a byte (not a pixel)	and #$FFFF-1	; make it even	sta FinishWord	lda >RightMaskTable+2,x	sta RightMask	rtl	ENDP****************************************************************** XSetUp640*****************************************************************XSetUp640	PROC EXPORT* Now we figure out	where in an even word, the first and last* pixels lie.  Then	we create a masks to protect the pixels* that are not to be touched.	lda X1	; convert local coordinates to	sec	; memory coordinates	sbc BoundsRect+2	; start with left point	tay	; save a copy in y	and #7	; mask off all but low 3 bits	asl a	; double this and put in	tax	; x	tya	; retrieve y	lsr a	; divide by 4 so refers to addr	lsr a	; of a byte	and #$FFFF-1	; make it even	sta StartWord	lda >LeftMaskTable,x	sta LeftMask	lda X2	; convert local coordinates to	clc	; than coordinate	sbc BoundsRect+2; was this, but change thar sec above and presto!; dec a	; last pixel touched is one less	tay	; save it in y	and #7	; mask off all but low 3 bits	asl a	; double this	tax	; put in x	tya	; retrieve y	lsr a	; divide by 4 so points to byte	lsr a	and #$FFFF-1	; make even	sta FinishWord	lda >RightMaskTable,x	sta RightMask	rtl	ENDP****************************************************************** LeftMaskTable** This table is not	what you think.  Since the words in* the scan line have the pixels in byte	order (not word order)* the mask must be reversed.  The b declaration does that* because it reads information a byte at a time in the order* it finds it.  So the bits on the left	appear in the low* byte of the table	entry while the bits on the right* appear in the high byte of the table entry.*****************************************************************LeftMaskTable	PROC EXPORT	DC.B %11111111,%11111111	DC.B %00111111,%11111111	DC.B %00001111,%11111111	DC.B %00000011,%11111111	DC.B %00000000,%11111111	DC.B %00000000,%00111111	DC.B %00000000,%00001111	DC.B %00000000,%00000011	ENDP****************************************************************** RightMaskTable*****************************************************************RightMaskTable	PROC EXPORT	DC.B %11000000,%00000000	DC.B %11110000,%00000000	DC.B %11111100,%00000000	DC.B %11111111,%00000000	DC.B %11111111,%11000000	DC.B %11111111,%11110000	DC.B %11111111,%11111100	DC.B %11111111,%11111111	ENDP;                copy RECTS/common****************************************************************** Common routine to	set up everything needed when drawing* slabs.** For this to work we use one new equate called WhosCalling.* This is set to DrawNoun-1.  This lets	us make the following* assumptions**       Noun	       Bits in WhosCalling**       RectNoun = $30     bit 15 clear	  bit 14 clear*       RgnNoun = $80      bit 15 set	  bit 14 clear*       RRectNoun =	$40    bit 15 clear	  bit 14 set*       OvalNoun = $50     bit 15 clear	  bit 14 set*       ArcNoun = $60      bit 15 clear	  bit 14 set** In this way we can to a BIT WhosCalling an know exactly* which of the three possible drawing routines will be used.** I wish I could claim credit for discovering this.  Actually, Art* looked at the nouns and made this observation.  Good work	Art.*****************************************************************CommonSlabSetup	PROC EXPORT	jsr CheckPenVis	; if the pen is not	visible there is*		; no return	jsl PortLoc2ZP	; all routines need	this done.	Export CommonSlabSetup2CommonSlabSetup2	jsl SetUpPortRegions ; all routines need this done.	bit WhosCalling	bpl NotRgn	jsr DerefC	; first deref the handle in RgnHandleC	jsr GetBoundsC	; Region calls bounding box of RGN C*		; moved to min rect.	jsl MakeMinRect	; so it does not use BMinRect	bra MinRectDoneNotRgn	jsl BMakeMinRectMinRectDone	bcs NeverMind	bit WhosCalling	bvs ItsConics	jsr MinRectToY1ItsConics		; ;-----------------------------------------------------;; Do right thing to	pattern given what we are doing.;	lda DrawVerb	asl a	tax	jsr (FixPatTable,x)	sta FillModePatIsReady		; 	jsl GetMaskReady	jsl ShieldCursor	jsl DoTheDrawing	jsl UnshieldCursorNeverMind	jsl FreePortRegions	bit <WhosCalling	bpl NotRgn2	jsr UnlockCNotRgn2		; 	lda #0	clc	rtlFixPatTable	DC.W ForPaint	; this will never be used	DC.W ForPaint	DC.W ForErase	DC.W ForInvert	DC.W ForFillForPaint		; 	jsl GetPenPReady	ldy #o_PnMode	lda [PortRef],y	rtsForErase		; 	jsl GetBackPReady	lda #modecopy	rtsForInvert		; 	ldx #512	; test to see if we can use the dirty flag stuff	lda <DirtyDPFlags,x	bpl @GoSlow	tay	; save this value for a sec...	and #InvPatternOK	; see if its ok to draw...	bne @PatternDone	tya	; get the flags back	and #AllPatsBad	ora #InvPatternOK+SolidPatOK	sta <DirtyDPFlags,x@GoSlow	lda #$FFFF	ldx #256@PatLoop	sta TheFillPat,x	inx	inx	cpx #PatSize+256	bcc @PatLoop@PatternDone	lda #ModeXOR	rtsForFill		; 	lda BoundsRect+2	and #7	tay	jsl RotatePat	lda #ModeCopy	rtsDoTheDrawing		; 	bit WhosCalling	bmi ItsRgn	bvs ItsConics2	jml DrawRectItsRgn	jml DrawRgnItsConics2	jml DrawConic	ENDP;                COPY RECTS/RECTS****************************************************************** FrameRect  (r : rect)** Modifications**    April 7, 1986	   Now returns error from CallRect.*****************************************************************FrameRect	PROC EXPORT	ldx #FrameVerb	bra JoinRect	ENDP****************************************************************** PaintRect    (r :	rect)** Modifications**    April 7, 1986	   Now returns error from CallRect.*	      ****************************************************************PaintRect	PROC EXPORT	ldx #PaintVerb	bra JoinRect	ENDP****************************************************************** EraseRect    (r :	rect)** Modifications**    April 7, 1986	   Now returns error from CallRect.*	       ****************************************************************EraseRect	PROC EXPORT	ldx #EraseVerb	bra JoinRect	ENDP****************************************************************** InvertRect   (r :	rect)** Modifications**    April 7, 1986	   Now returns error from CallRect.*                 ****************************************************************InvertRect	PROC EXPORT	ldx #InvertVerb; let this one fall	into join rect	ENDP****************************************************************** JoinRect** JoinRect is a common routine called by frame, paint,invert* and erase rect.  The draw verb is passed in X** Modifications**    Apr 14, 1989	   QDStart is now inline and the jmp BusyErr8*	   is long so it can work in the patch.****************************************************************JoinRect	PROC EXPORT	phd	tcd	lda >BusyFlag	inc a	sta >BusyFlag;; DEBUG HERE;;	lda >$E0C025;	and #$0004;	beq @NoDebug;	brk 00;@NoDebug	stx DrawVerb	; save draw verb on	zp	jsr GetRect	; get the rect to zp	ldx DrawVerb	; get the draw verb	back	jsl CallRect	; call rect	tax	; return any error	jml BusyErr4	ENDP****************************************************************** FillRect     (r :	rect; p : pattern)** Modifications**    April 7, 1986	   Now returns error from CallRect.**    Feb 25, 1987	   Now calls QDStart at beginning!**    Apr 14, 1989	   QDStart is now inline and the jmp BusyErr8*	   is long so it can work in the patch.*****************************************************************FillRect	PROC EXPORTOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PPtr	equ RTL2+3RPtr	equ PPtr+4	phd	tcd	lda >BusyFlag	inc a	sta >BusyFlag	jsl UserPat2ZP	lda RPtr,s	sta PPtr,s	lda RPtr+2,s	sta PPtr+2,s	jsr GetRect	ldx #FillVerb	jsl CallRect	tax	jml BusyErr8			ENDP****************************************************************** GetRect** Internal routine to move the rectangle pointed to by* the pointer on the stack to Y1 etc.** This routine trashes temp (four bytes	on zp) and* all registers.*****************************************************************GetRect	PROC EXPORTRTSAdr	equ 1OrigDirect	equ RTSAdr+2RTL1	equ OrigDirect+2RTL2	equ RTL1+3RPtr	equ RTL2+3	lda RPtr,s	sta Temp	lda RPtr+1,s	sta Temp+1	ldy #6PLoop	tyx	lda [Temp],y	sta Y1,x	dey	dey	bpl PLoop	rts	ENDP****************************************************************** CallRect** This routine is jumped (or branched) to by the* entry points after the graf verb is loaded into the* x register.** Zero page is already switched in by the time it gets here.*****************************************************************CallRect	PROC EXPORT; The following code is pretty handy when debugging rects, tryit, you'll like it...;@wait	lda >$E0C000;	bpl @Wait;	sta >$E0C010;	and #$7F;	cmp #$1B;	bne @NoDebug;	brk 00@NoDebug	stx DrawVerb	lda #RectNoun	;	sta DrawNoun	; put on zp for later too!!!!		ldx #512	; test the DirtyDPFlags for picts and pen...	lda <DirtyDPFlags,x	and #TestDrawState	cmp #TestDrawState	beq DoFasterSetup	; if this is zero, then pen vis/no pictures etc...	jsr TestGPs	; if there is a gp pointer	bcs UseLocal	jml StdRectUseLocal	phb	; put extra byte on	stack	ldy #o_stdrect	; get adr of new rect routine	lda [temp],y	; put on stack	pha	iny	; get bytes 2 and 3	lda [temp],y	sta 2,s	; store middle byte	twice	rtl	; call itDoFasterSetup	lda DrawVerb	; put verb in a	bne NotFrame	jmp FrRectNotFrame	jmp CommonSlabSetup2	ENDP****************************************************************** StdRect** Common rectangle routine that is central point for* all rectangle drawing routines.** When control gets	here, all inputs are on zero page.*       TheRect is kept in Y1 thru X2*       ThePat (if any) is in TheFillPat*       WhatToDo is	in DrawVerb** Modifications**   April 7, 1986	  Now checks error returns from PutPicStuff*	  and PutRect.*****************************************************************iStdRect	PROC EXPORT	lda #RectNoun	;	sta DrawNoun	; put on zp for later too!!!!		jsl PutPictStuff	; inputs on zp and in a-reg	bcc NoPicErr	rtl	; return the errorNoPicErr		; 	lda DrawVerb	; put verb in a	bne NotFrame	jsr RgnSave	; does this contribute to region def	bcc FrRect	; no, so frame it	jsl PutRect	; yes, so call putrect	bcc FrRect	; no error so frame	it.	rtl	; return the errorNotFrame		; 	jmp CommonSlabSetup	ENDP****************************************************************** PRect, FRect, IRect, ERect*****************************************************************PRect	PROC EXPORT	ENDPFRect	PROC EXPORT	ENDPIRect	PROC EXPORT	ENDPERect	PROC EXPORT	lda #RectNoun	sta DrawNoun	jmp CommonSlabSetup	ENDP****************************************************************** FrRect** Modifications**     April 7, 1986	  Now returns "No Error"*****************************************************************FrRect	PROC EXPORT	jsr GrabPenSize	; don't come back unless visible	jsr CheckPenVis	; don't come back unless visible;-------------------------------------------------;; Put copy of rect in rect2;	lda y1	sta Rect2	lda Y1+2	sta Rect2+2	lda Y1+4	sta Rect2+4	lda Y1+6	sta Rect2+6; was;	ldx #6;Loop	lda Y1,x;	sta Rect2,x;	dex;	dex;	bpl Loop;-------------------------------------------------;; Check to see if this is a valid rectangle	jsl PreDraw	; move stuff to zp	jsl SetUpPortRegions	jsl BMakeMinRect	bcc ValidRect	jsl FreePortRegions	rtlValidRect	jsl ShieldCursor;-------------------------------------------------;; See if the pen size is larger than rectangle;	ldx #2CheckLoop	lda Rect2+4,x	sec	sbc Rect2,x	lsr a	cmp LocalPnSize,x	bcc PenTooBig	dex	dex	bpl CheckLoop	bra PenOkayPenTooBig	jsl DrawRectB	bra FinishIt;-----------------------------------------------;; We draw four rectangles in such a way	that ; no pixel is drawn	more than once;PenOkay	lda Y1	; first the top of the rect	clc	adc LocalPnSize	sta Y2	jsl DrawRectB;	lda Rect2+o_H2	sta x2	sec	sbc LocalPnSize+2	sta x1		lda Rect2+o_V2	sta Y2		lda Rect2+o_V1	clc	adc LocalPnSize	sta Y1	jsl DrawRectB;	lda Rect2+o_H2	sec	sbc LocalPnSize+2	sta X2	lda Rect2+o_V2	sta Y2	sec	sbc LocalPnSize	sta Y1	lda Rect2+o_H1	sta X1	jsl DrawRectB;	lda Rect2+o_V2	sec	sbc LocalPnSize	sta Y2		lda Rect2+o_H1	sta X1	clc	adc LocalPnSize+2	sta X2		lda Rect2+o_V1	clc	; edges since they are already	adc LocalPnSize	; done	sta Y1	jsl DrawRectBFinishIt	jsl UnshieldCursor	jsl FreePortRegions	lda #0	; return no error	clc	rtl	ENDP****************************************************************** DrawRect** Draws the specified rectangle using the pattern kept in* TheFillPat, using	the mode kept in FillMode** 2/22/89	Konstantin & Dave**	Changed SetSlabAdr so that the carry is clear* when the clip region is rectangular and the draw mask is all $FFFF.** 2/24/89	Konstantin*	If the regions are rectangular, we don't need to call*	Init2Regions.** 3/3/89	Mensch*	Add faster "thin rect" drawing. This should speed*	up framerect a bunch!** 3/10/89	Mensch (and Dave)*	Changed the "thin rect" stuff to allow use to call*	some new super slab routines** 4/22/89	Mensch*	Fixed all super slab (non-slabs actually) to take*	the proper word of the pattern for screen blitting*****************************************************************iDrawRectB	PROC EXPORT;---------------------------------------------------------------	EXPORT iDrawRect	IMPORT  FastDrawRect;---------------------------------------------------------------;---------------------------------------------------------------	jsl  BMakeMinRect	jsr  MinRectToY1	bcc  iDrawRect	rtl;---------------------------------------------------------------iDrawRect	phb		;save the data bank register	lda  [RgnPtrA]	ora  [RgnPtrB]	cmp  #10		bne  GoSlow	stz  NonRectRegions	jsl  SetSlabAdr	bcc  FastDrawRect;---------------------------------------------------------------GoSlow	jsl  Init2Regions	jsl  SetSlabAdr	jsl  XSetup	jsr  SetFirstDestRef	;set up dest ref for first scan lineRectLoop	jsr  NextPatSlice		;set up the next pattern slice	jsl  Seek2Regions		;seek regions to this line	jsl  ToSlab		;draw this slab	lda  CurrentY		;bump current Y	inc  a	cmp  Y2	bpl  TheEnd	sta  CurrentY	jsr  SetNextDestRef	bra  RectLoopTheEnd	plb		;restore the bank register	rtl;---------------------------------------------------------------	ENDP****************************************************************FastDrawRect	PROC;---------------------------------------------------------------	IMPORT  EndXORRazor	IMPORT  CopyJumpTable;---------------------------------------------------------------;---------------------------------------------------------------patIndex	equ  CurrentYlineCount	equ  Y2;---------------------------------------------------------------;---------------------------------------------------------------	jsl  XSetup		;setup for calling the slabs	jsr  SetFirstDestRef	pei  Y2		;save Y2	lda  Y2		;find the line count (bottom - top)	sec	sbc  CurrentY	sta  lineCount	lda  FillMode		;if the fill mode is not modeCopy	and  #$7F		;..or modeXOR, then use the slabs	beq  @1	cmp  #modeXOR	bne  useTheSlabs@1	lda  FinishWord		;If we are only doing one or two words,	sec		;..then special case these	sbc  StartWord	beq  doSingle	lsr  a	dec  a	beq  @gotoEdges	cmp  #80		;if we are using more than 80 words then	bge  useTheSlabs		;..use the slabs	sta  Temp		;save the count in direct page	ldx  #512		;if we are using solid patterns then	lda  <DirtyDPFlags,x	;..do a special loop	and #SolidPatOK	cmp #SolidPatOK	bne  useTheSlabs	jmp  fastMiddle@gotoEdges	jmp  doEdges;---------------------------------------------------------------;---------------------------------------------------------------useTheSlabs	jsr  makePatIndex		;find the index into the FillPat table@loop	lda  TheFillPat,x		;put the pattern in Pat	sta  Pat	lda  TheFillPat+2,x	sta  Pat+2	lda  FillMode		;do we need to invert the pattern ?	bpl  @notNOT	lda  Pat	eor  #$FFFF	sta  Pat	lda  Pat+2	eor  #$FFFF	sta  Pat+2@notNOT	jsl  ToSlab		;draw the actual line	dec  lineCount	beq  allDone	lda  patIndex		;move to the next pattern	clc	adc  #4	and  #$011F	sta  patIndex	tax	lda  DestRef		;move to the next line. NOTE: carry is	adc  Width		;..always clear here	sta  DestRef	bcc  @loop	inc  DestRef+2	pei  DestRef+1	plb	plb	bra  @loop;---------------------------------------------------------------allDone	pla	sta  Y2	plb	rtl;---------------------------------------------------------------;---------------------------------------------------------------doSingle	ldx  #512		;if we are using solid patterns then	lda  <DirtyDPFlags,x	;..do a special loop	and #SolidPatOK	cmp #SolidPatOK	bne  slowSingle	ldx  #256	lda  TheFillPat,x	sta  Pat	ldx  FillMode	bpl  @notNOT	eor  #$FFFF	sta  Pat@notNOT	ldy  StartWord		;our offset stays the same	ldx  lineCount	lda  FillMode		;..copy or an XOR	and  #$7F	beq  singleCopy;---------------------------------------------------------------singleXOR	lda  Pat		;combine the pattern with the mask	and  LeftMask	and  RightMask	sta  Pat@slowLoop	clc		;clear the carry@loop	lda  Pat	eor  (DestRef),y	sta  (DestRef),y	dex	beq  AllDone	lda  DestRef		;move to the next line. NOTE: carry is	adc  Width		;..always clear here	sta  DestRef	bcc  @loop	inc  DestRef+2	pei  DestRef+1	plb	plb	bra  @slowLoop;---------------------------------------------------------------singleCopy	lda  LeftMask		;combine our masks so we only need one	and  RightMask	sta  LeftMask@slowLoop	clc		;clear the carry@loop	lda  Pat	eor  (DestRef),y	and  LeftMask	eor  (DestRef),y	sta  (DestRef),y	dex	beq  gotoAllDone1	lda  DestRef		;move to the next line. NOTE: carry is	adc  Width		;..always clear here	sta  DestRef	bcc  @loop	inc  DestRef+2	pei  DestRef+1	plb	plb	bra  @slowLoopgotoAllDone1	jmp AllDone;---------------------------------------------------------------slowSingle	jsr  makePatIndex		;find the index into the FillPat table; 4/22/89 Mensch; Modified to support 32 byte patterns	lda <STartWord	and #$0002	beq @1	inx	; if odd bump pattern address by 2...	inx@1	lda  LeftMask		;combine our masks so we only need one	and  RightMask	sta  LeftMask	stz  Pat+2		;use Pat+2 to take care of the not mode	lda  FillMode		;..for the pattern	bpl  @notNOT	dec  Pat+2@notNOT	ldy  StartWord		;our offset stays the same	stz  Temp		;temp tells us whether we are doing a	lda  FillMode		;..copy or an XOR	and  #$7F	beq  @slowLoop	dec  Temp		;here we are doing an XOR@slowLoop	clc@loop	lda  TheFillPat,x		;put the pattern in Pat	eor  Pat+2		;take care of the NOT case	bit  Temp	bmi  @2	eor  (DestRef),y@2	and  LeftMask	eor  (DestRef),y	sta  (DestRef),y	dec  lineCount	beq  gotoAllDone	txa		;move to the next pattern	adc  #4		;carry is ALWAYS clear here	and  #$011F	tax	lda  DestRef		;move to the next line. NOTE: carry is	adc  Width		;..always clear here	sta  DestRef	bcc  @loop	inc  DestRef+2	pei  DestRef+1	plb	plb	bra  @slowLoop;---------------------------------------------------------------gotoAllDone	jmp  allDone;---------------------------------------------------------------;---------------------------------------------------------------doEdges		ldx  #512		;if we are using solid patterns then	lda  <DirtyDPFlags,x	;..do a special loop	and #SolidPatOK	cmp #SolidPatOK	bne slowEdges	ldx #256	lda  TheFillPat,x	sta  Pat	ldx  FillMode	bpl  @notNOT	eor  #$FFFF	sta  Pat@notNOT	ldx  lineCount	lda  FillMode		;..copy or an XOR	and  #$7F	beq  edgeCopy;---------------------------------------------------------------edgeXOR	lda  Pat	tay	and  LeftMask	sta  Pat	tya	and  RightMask	sta  Pat+2@slowLoop	clc@loop	ldy  StartWord	lda  Pat	eor  (DestRef),y	sta  (DestRef),y	iny	iny	lda  Pat+2	eor  (DestRef),y	sta  (DestRef),y	dex	beq  gotoAllDone	lda  DestRef		;move to the next line. NOTE: carry is	adc  Width		;..always clear here	sta  DestRef	bcc  @loop	inc  DestRef+2	pei  DestRef+1	plb	plb	bra  @slowLoop;---------------------------------------------------------------edgeCopy	clc@loop	ldy  StartWord	lda  Pat	eor  (DestRef),y	and  LeftMask	eor  (DestRef),y	sta  (DestRef),y	iny	iny	lda  Pat	eor  (DestRef),y	and  RightMask	eor  (DestRef),y	sta  (DestRef),y	dex	beq  gotoAllDone	lda  DestRef		;move to the next line. NOTE: carry is	adc  Width		;..always clear here	sta  DestRef	bcc  @loop	inc  DestRef+2	pei  DestRef+1	plb	plb	bra  edgeCopy;---------------------------------------------------------------slowEdges	jsr  makePatIndex		;find the index into the FillPat table	stz  Temp		;temp tells us whether we are doing a	lda  FillMode		;..copy or an XOR	and  #$7F	beq  @slowLoop	dec  Temp		;here we are doing an XOR@slowLoop	clc@loop	lda  StartWord	; Modified 4/22/89 mensch	tay	; make this change to support 32 byte patterns	and #$0002	beq @EvenPat	; if zero use pats in order	lda TheFillPat,x	; else swap em...	sta Pat+2	; first store the 2nd word pattern	lda TheFillPat+2,x	bra @OddPat@EvenPat	lda TheFillPat+2,x	; store the 2nd word pattern	sta Pat+2	lda  TheFillPat,x	;Now get first word pat@OddPat	bit  FillMode	bpl  @notNOT1	eor  #$FFFF@notNOT1	bit  Temp	bmi  @1	eor  (DestRef),y@1	and  LeftMask	eor  (DestRef),y	sta  (DestRef),y	iny	iny	lda  Pat+2	;put the pattern in Pat	bit  FillMode	bpl  @notNOT2	eor  #$FFFF@notNOT2	bit  Temp	bmi  @2	eor  (DestRef),y@2	and  RightMask	eor  (DestRef),y	sta  (DestRef),y	dec  lineCount	beq  edgeDone	lda  patIndex		;move to the next pattern	adc  #4		;carry is ALWAYS clear here	and  #$011F	sta  patIndex	tax	lda  DestRef		;move to the next line. NOTE: carry is	adc  Width		;..always clear here	sta  DestRef	bcc  @loop	inc  DestRef+2	pei  DestRef+1	plb	plb	bra  @slowLoop;---------------------------------------------------------------edgeDone	jmp  allDone;---------------------------------------------------------------;---------------------------------------------------------------fastMiddle	ldx  #256		;if we are using extended patterns, then	lda  TheFillPat,x		;..call the slabs	sta  Pat	cmp  TheFillPat+2,x	bnel useTheSlabs	ldx  FillMode		;do we need to invert the pattern ?	bpl  @dontInvert	eor  #$FFFF	sta  Pat@dontInvert	txa		;get back the fill mode	and  #$7F	beq  @setupCopy@setupXOR	lda  Temp	asl  a		;multiply the count by seven (the number	asl  a		;..of bytes of code it takes to XOR one	asl  a		;..word.)	sbc  Temp		;NOTE: the carry is always CLR here so	eor  #$FFFF		;..these three lines get us:	adc  #EndXORRazor-2		;..{ EndXORRazor - (count * 7) - 1 }	bra  @cont@setupCopy	lda  Temp	asl  a	tax	lda  >CopyJumpTable,x	dec  a@cont	sta  Temp		;save the jump address for the slab hooks	pei  FinishWord		;save FinishWord, since we kill it	ldx  Pat		;keep the pattern in the X-Reg	lda  FinishWord		;adjust the finish word so we can use it	sec		;..as an index easier	sbc  StartWord	sta  FinishWord	lda  StartWord		;make Y-Reg a pointer to the first word	clc		;..to invert	adc  DestRef	tay	lda  FillMode		;are we using copy or XOR ?	and  #$7F	beq  @enterCopyLoop	bra  @enterXORLoop;---------------------------------------------------------------@copyLoop	txa	eor  |0,y	and  LeftMask	eor  |0,y	sta  |0,y	sty  DestRef		;save our index in DestRef	ldy  FinishWord		;the last word is always at finish word	txa		;source pattern is still in X-Reg	eor  (DestRef),y	and  RightMask	eor  (DestRef),y	sta  (DestRef),y		;and store	ldy  DestRef	txa		;copy needs the pattern in the A-Reg	pea  @backHere1-1	pei  Temp	rts@backHere1	dec  lineCount	beq  middleDone	tya		;the carry is always clear here	adc  Width	tay@enterCopyLoop	bcc  @copyLoop	clc		;the carry must remain clear thru this	inc  DestRef+2		;..loop	pei  DestRef+1	plb	plb	bra  @copyLoop;---------------------------------------------------------------@XORLoop	txa		;invert our first word using the only	and  LeftMask		;..pattern and leftMask	eor  |0,y	sta  |0,y	sty  DestRef		;save our index in DestRef	ldy  FinishWord		;the last word is always at finish word	txa		;source pattern is still in X-Reg	and  RightMask	eor  (DestRef),y	sta  (DestRef),y		;and store	ldy  DestRef	pea  @backHere2-1		;pattern in A-Reg; XOR needs it in X-Reg	pei  Temp	rts@backHere2	dec  lineCount	beq  middleDone	tya	adc  Width		;the carry is always clear here	tay@enterXORLoop	bcc  @XORLoop	clc		;the carry must remain clear thru this	inc  DestRef+2		;..loop	pei  DestRef+1	plb	plb	bra  @XORLoop;---------------------------------------------------------------middleDone	pla	sta  FinishWord	jmp  allDone;---------------------------------------------------------------;---------------------------------------------------------------makePatIndex	lda  CurrentY		;find the current index into the FillPat	and  #7		;..table	asl  a	asl  a	adc  #256	sta  patIndex	tax	rts;---------------------------------------------------------------	ENDP********************************************************************************************************************************** CheckPenVis** This routine makes sure that the pen is visible. It is called* as quickly as possible after the bottle neck proc so if the* pen is not visible, we can quit fast.** If the pen is not	visible, then we perform the RTL for the* calling routine.** Modification History** 19 May 86    When	pen is not visible we must*              clear carry and zero accumulator so proper*              error is propagated.** 3/9/89	Mensch* Added adjustment of DirtyDPFlags to this routine...*****************************************************************CheckPenVis	PROC EXPORT	ldy #o_PnVis	lda [PortRef],y	bmi NotVisible	ldx #512	lda <DirtyDPFlags,x	ora #PenVisOK	sta <DirtyDPFlags,x	rtsNotVisible	pla	; pull rts adr off stack	clc	; clear carry and a-reg so no	lda #0	; error is returned.	rtl	; do rtl for caller.	ENDP****************************************************************** GrabPenSize** Get the PnSize from the port and puts	it in LocalPnSize.* It also checks to	see if either is 0.	 If it is then* we do an rtl for the calling routine.** Modification History** 19 May 86    When	pen size is less than one then we must*              clear carry and zero accumulator so proper*              error is propagated.*****************************************************************GrabPenSize	PROC EXPORT	ldy #O_PnSize	lda [PortRef],y	beq NowWaitAMin	sta LocalPnSize	iny	iny	lda [PortRef],y	beq NowWaitAMin	sta LocalPnSize+2	rtsNowWaitAMin	pla	; get rts adr off stack	clc	; remember that this terminates call	lda #0	; with no error	rtl	; do rtl for calling routine	ENDP*********************************************************************** SetFirstDestRef** History* 8/4/87       GCP	         Installed patch version of this routine** 2/25/89	Mensch* Added a faster inline multiply just for grins. Speed this routine up* quite a lot and seems to complement those new faster rectangles pretty* well.*********************************************************************SetFirstDestRef	PROC EXPORTMult1	equ DestRefMult2	equ DestRef+2	pea 0	;assume its positive	lda Y1	;now figure out where in the	sta CurrentY	;pixel map this scan line	sec	;is	sbc BoundsRect	bpl ItsPositive	sta 1,s	eor #$FFFF	inc aItsPositive; since we are resetting destref, lets have some fun and use it for a temp; Comming into this loop <A> contains the scan line number; so we first see if we rolled off the "Dave" limit	sta Mult1	; lets save it for a sec as an operand.....	cmp #400	; see if we rolled over the top of the mult below	bge @DoMultSlow	lda <Width	cmp #$00A0	; is it scan line size???	bne @DoMultSlow	lda Mult1	; get our number back...	asl a	; multiply it by 32 first..	asl a	asl a	asl a	asl a	sta Mult1	asl a	asl a	clc	adc Mult1	pea 0	pha	bra @DoMultDone@DoMultSlow	;; the damned fast multiply that I put in fails on enormous drawings (Damn); so, we put back the old multiply routine so we can ship the damned disk!; Mensch 6/13/89	pha	pha	pei Mult1	pei Width	_Multiply;; Fast multiply routine, just in case I need it for something!;;	ldx #0	; init our carry over area;	lda #0;@dm0010	lsr Mult1	; shift for first test;	beq @dmLastOne	; handle the last multiply;	bcc @dm0020;	clc;	adc Mult2;	bcc @dm0020	; if carry clear we didn't role the bank yet..;	inx	; if carry set, role the bank!;@dm0020	asl Mult2;; Bug fix here...;	bcc @dm0010;	inx;	bra @dm0010;@dmLastOne	bcc @DoMultDone;	clc;	adc Mult2;	bcc @DoMultDone	; carry clear no bank role;	inx	;olddoMultDone	phx	; push the high word;	pha	; and the low word@DoMultDone	lda 5,s	bne MustSubtract	pla	clc	adc ImageRef	; low word of image	ref	sta DestRef	;goes into dest ref	pla	adc ImageRef+2	;hi word of image ref	and #$00FF	;mask off higest byte for system wins	bra FinishKludgeMustSubtract		; 	lda ImageRef	;subtract result from pointer to image	sec	sbc 1,s	sta DestRef	lda ImageRef+2	sbc 3,s	plx	plxFinishKludge	sta DestRef+2	pla;-------------------------------------------------------;; Now set data bank	to  bank containing	this scan line;	pei DestRef+1	plb	plb		rts	ENDP****************************************************************** NextPatSlice** Using currentY I pull out the correct	part of the pattern* and draw mask to be drawn.*** Change History** 08 Sep 88	Steven Glass** Patterns are always 32 bytes (no matter what the mode).*****************************************************************NextPatSlice	PROC EXPORT	lda CurrentY	and #7	; pattern repeats every 8 lines	asl a	; pattern 4 bytes wide	asl a	clc	adc #256	tax	lda TheFillPat,x	sta Pat	lda TheFillPat+2,x	; this is wasted in	640 mode but	sta Pat+2	; not harmful	lda TheDrawMask,x	sta DrawMask	lda TheDrawMask+2,x	sta DrawMask+2	lda FillMode	; if pen mode is a NOT mode, then	bpl NotNOT	; invert pat	lda Pat	eor #$FFFF	sta Pat	lda Pat+2	eor #$FFFF	sta Pat+2NotNOT		; 	rts	ENDP****************************************************************** SetNextDestRef** This routine bumps DestRef by width.	It does a full 32 bit* add.  If the add carries to the high word it resets the* data bank to the new value.*****************************************************************SetNextDestRef	PROC EXPORT	lda DestRef	clc	adc Width	sta DestRef	bcs MustCarry	rtsMustCarry	inc DestRef+2	pei DestRef+1	plb	plb	rts	ENDP	EJECT	END